const dateMode=ref('all'),focus=ref('all'),scopeProductKey=ref(''),batchScopes=ref<Record<string,BatchFilter>>({}),batchSections=ref<Record<string,BatchSection>>({}),pairs=ref<Record<string,string[]>>({}),gapOwner=ref(''),gapCode=ref(''),periodKind=ref('')
