async function load(criteria:CostFilters=activeFilters()){if(jobTimer!==undefined)window.clearTimeout(jobTimer);const epoch=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';try{const next=await request<Report>(api.value+'?'+new URLSearchParams(criteria),undefined,controller.signal);if(epoch!==generation)return
