async function exportGaps(){toolsOpen.value=false;const rows=gapRows.value,at=new Date(),stamp=at.toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}),snap=report.value?.sourceRevision?'快照 '+String(report.value.sourceRevision).slice(0,12)+' · '+bjTime(report.value.sourceCheckedAt):cfg.value.label+'工作区当前记录';const IMP=['影响单位成本','只影响人均 / 工序分摊'],head=['工单','产品','影响','缺什么','原因','补齐后能解决','另有','跟进'],byOwner=new Map<string,string[][]>(),cnt=new Map<string,[number,number]>();let nUnit=0;for(const {o,g} of rows){const k=g.owner||'未指定',u=!!g.blocksUnitCost;if(u)nUnit++;if(!byOwner.has(k)){byOwner.set(k,[]);cnt.set(k,[0,0])}cnt.get(k)![u?0:1]++;byOwner.get(k)!.push([o.projectCode,o.product,IMP[u?0:1],g.label,g.reasons.join('；'),g.unlocks,g.others.join('、'),followLabel(o.followup?.status)])}const split=IMP[0]+' '+nUnit+' 张、'+IMP[1]+' '+(rows.length-nUnit)+' 张'
 try{const X=await import('xlsx');const wb=X.utils.book_new(),used=new Set<string>();X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet([['待补资料（按责任人）'],['工作区',cfg.value.label],['数据时点',snap],['导出时间（北京时间）',stamp],['筛选',report.value?.dateContext.label||''],['张数',rows.length],['其中 '+IMP[0],nUnit,'暂不能算单位成本，补齐后才能算'],['其中 '+IMP[1],rows.length-nUnit,'单位成本已可算、补了也不变；只缺实际参与名单或人时，补了才能算人均和工序分摊'],['口径','每张工单只出现一次，按主分类；未补的不补 0。各表「影响」列逐张标明。'],[],['责任人','张数',IMP[0],IMP[1]],...[...byOwner].map(([k,v])=>[k,v.length,cnt.get(k)![0],cnt.get(k)![1]])]),'说明');for(const [k,v] of byOwner){let n=k.replace(/[\\/?*\[\]:]/g,'／').slice(0,28);while(used.has(n))n=n.slice(0,26)+'_'+used.size;used.add(n);X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet([head,...v]),n)}X.writeFile(wb,cfg.value.factoryId.toLowerCase()+'-cost-gaps-by-owner.xlsx');notice.value='已导出待补清单（xlsx）：'+byOwner.size+' 位责任人、'+rows.length+' 张工单（'+split+'），数据时点 '+snap+'。';return}catch(e){notice.value='xlsx 导出不可用（'+(e instanceof Error?e.message:'未知原因')+'），改为按责任人分组的 CSV。'}
 const esc=(v:string)=>'"'+String(v).replaceAll('"','""')+'"',lines=[esc('数据时点：'+snap+'；导出时间（北京时间）：'+stamp+'；'+split),['责任人',...head].map(esc).join(',')];for(const [k,v] of byOwner)for(const r of v)lines.push([k,...r].map(esc).join(','));const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\r\n')],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download=cfg.value.factoryId.toLowerCase()+'-cost-gaps-by-owner.csv';document.body.append(a);a.click();a.remove();window.setTimeout(()=>URL.revokeObjectURL(url),1000)}
// ---- BL16 工价规则 / BL14 估值单价（Cretas 补充，均可撤销、留痕；不改黑湖） ----
interface WageRule{id:string;processId:string;processName:string|null;productCode:string|null;mode:'piece'|'time';rate:number;unit:string;effectiveFrom:string|null;evidence:string;at:string;revokedAt?:string;revokeReason?:string}
const wages=ref<{version:number;prices:{key:string;productCode:string;unit:string;unitPrice:number;evidence:string;at:string;revokedAt?:string;revokeReason?:string}[];rules:WageRule[];processes:{id:string;name:string}[];coverage:{reports:number;matched:number;reasons:{reason:string;count:number}[]}}|null>(null),ruleForm=ref({processId:'',productCode:'',mode:'time',rate:'',unit:'',effectiveFrom:'',evidence:''}),ruleOpen=ref(false),priceOpen=ref(false),priceForm=ref({productCode:'',unit:'',unitPrice:'',evidence:''})
async function loadWages(){try{wages.value=await request(api.value+'/wage-rules')}catch(e){error.value=e instanceof Error?e.message:'工价规则读取失败'}}
watch(view,v=>{if(v==='wages')void loadWages()},{immediate:true})
async function saveRule(){if(saving.value||!report.value)return;saving.value=true;error.value='';const before=report.value.eligibleCount;try{const f=ruleForm.value;await request(api.value+'/wage-rule',{expectedVersion:report.value.version,processId:f.processId,productCode:f.productCode.trim()||null,mode:f.mode,rate:numeric(f.rate),unit:f.unit,effectiveFrom:f.effectiveFrom||null,evidence:f.evidence});ruleOpen.value=false;await load();await loadWages();notice.value='工价规则已保存并重算：报工匹配 '+(wages.value?.coverage.matched??0)+' / '+(wages.value?.coverage.reports??0)+' 条，可算工单 '+before+' → '+(report.value?.eligibleCount??before)+' 张（黑湖有工资的工单仍以黑湖为准）。'}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
function revokePrice(key:string){askRevoke('撤销补充估值单价',key,'该物料回到黑湖正价领料单价或「未估值」；留痕保留。',async reason=>{lastResult.value=null;notice.value='';await request(api.value+'/valuation-price-revoke',{expectedVersion:report.value!.version,key,reason});await load();await loadWages();notice.value='已撤销补充估值单价 '+key+'。'})}
function revokeRule(r:WageRule){askRevoke('撤销工价规则',r.id+' · '+(r.processName||r.processId)+' · '+(r.mode==='piece'?'计件':'计时')+' '+fmt(r.rate)+' / '+r.unit,'相关报工不再按这条规则计算，黑湖缺人工费的工单会回到「未提供」；留痕保留。',async reason=>{lastResult.value=null;notice.value='';await request(api.value+'/wage-rule-revoke',{expectedVersion:report.value!.version,ruleId:r.id,reason});await load();await loadWages();notice.value='已撤销工价规则 '+r.id+'：报工匹配 '+(wages.value?.coverage.matched??0)+' / '+(wages.value?.coverage.reports??0)+' 条。'})}
function openPrice(){priceForm.value={productCode:'',unit:'',unitPrice:'',evidence:''};priceOpen.value=true}
async function savePrice(){if(saving.value||!report.value)return;saving.value=true;error.value='';try{const f=priceForm.value;await request(api.value+'/valuation-price',{expectedVersion:report.value.version,productCode:f.productCode,unit:f.unit,unitPrice:numeric(f.unitPrice),evidence:f.evidence});priceOpen.value=false;notice.value='估值单价已作为 Cretas 补充保存（'+f.productCode+' / '+f.unit+'），黑湖有正价领料时以黑湖为准。';await load();if(view.value==='wages')await loadWages()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
// ---- B9 周期：以最新有数据的日期为锚，按北京时间自然周期取范围（首尾含） ----
const anchor=computed(()=>{const d=allOrders.value.map(o=>o.at).filter(Boolean).map(v=>String(v).slice(0,10)).sort().at(-1);return d||new Date().toISOString().slice(0,10)})
function iso(d:Date){return d.toISOString().slice(0,10)}
function setPeriod(kind:string){periodKind.value=kind;if(kind==='custom'){dateMode.value='custom';persist();return}const a=new Date(anchor.value+'T00:00:00Z');let s=new Date(a),e=new Date(a);if(kind==='week'){const w=(a.getUTCDay()+6)%7;s.setUTCDate(a.getUTCDate()-w);e=new Date(s);e.setUTCDate(s.getUTCDate()+6)}else if(kind==='month'){s=new Date(Date.UTC(a.getUTCFullYear(),a.getUTCMonth(),1));e=new Date(Date.UTC(a.getUTCFullYear(),a.getUTCMonth()+1,0))}else if(kind==='quarter'){const q=Math.floor(a.getUTCMonth()/3)*3;s=new Date(Date.UTC(a.getUTCFullYear(),q,1));e=new Date(Date.UTC(a.getUTCFullYear(),q+3,0))}else if(kind==='year'){s=new Date(Date.UTC(a.getUTCFullYear(),0,1));e=new Date(Date.UTC(a.getUTCFullYear(),11,31))}dateMode.value='custom';startDate.value=iso(s);endDate.value=iso(e);void applyFilters()}
async function locateSupplement(event:Event){const detail=(event as CustomEvent<{recordId:string;productKey:string}>).detail,p=report.value?.products.find(p=>p.key===detail.productKey),o=p?.orders.find(o=>o.id===detail.recordId);if(!o){notice.value='当前筛选已变化，请恢复原分析范围后再补资料。';return}environment.CretasSupplyAnalysis?.panelClose();productKey.value=p!.key;view.value='products';drawer.value=false;if(!o.processes.length){inspect(o,'evidence');notice.value='本工单需要先核对报工对应，已定位资料缺口和来源入口。';return}await nextTick();openEditor(o)}
async function analyzeOrder(o:Order){drawer.value=false;await nextTick();return environment.CretasSupplyAnalysis?.openCost({...activeFilters(),factoryId:cfg.value.factoryId,orderId:o.id,costView:true,productLabel:o.projectCode})}
function restore(){try{const saved=JSON.parse(localStorage.getItem(key())||'null');if(!saved||typeof saved!=='object'||Array.isArray(saved))return
  for(const [k,target]of Object.entries({keyword,startDate,endDate,unit,scopeProductKey,gapOwner,gapCode,periodKind}))if(typeof saved[k]==='string')target.value=saved[k]
  if(['all','recent','custom','undated'].includes(saved.dateMode))dateMode.value=saved.dateMode;if(['all','missing','readiness','difference'].includes(saved.attention))focus.value=saved.attention;if(typeof saved.chartScope==='string')chartScope.value=saved.chartScope
  const safe=(o:unknown)=>o&&typeof o==='object'&&!Array.isArray(o)?Object.entries(o as Record<string,unknown>).filter(([k])=>/^[A-Za-z0-9:_-]{1,128}$/.test(k)&&!['__proto__','constructor','prototype'].includes(k)):[]
  for(const [k,v] of safe(saved.batchScopes))if(['all','ready','missing'].includes(String(v)))batchScopes.value[k]=v as BatchFilter
  for(const [k,v] of safe(saved.batchSections))if(['material','labor','evidence'].includes(String(v)))batchSections.value[k]=v as BatchSection
  for(const [k,v] of safe(saved.pairs))if(Array.isArray(v)&&v.length===2&&v.every(x=>typeof x==='string'))pairs.value[k]=v as string[]
  if(typeof saved.batchId==='string')restoreBatchId=saved.batchId;if(VIEWS.value.some(v=>v.id===saved.view))view.value=saved.view;if(typeof saved.productKey==='string')productKey.value=saved.productKey;if(saved.sort==='cost')sort.value='cost';if(Number.isInteger(saved.productPage)&&saved.productPage>0)productPage.value=saved.productPage;if(saved.showCharts===true)showCharts.value=true}catch{notice.value='筛选偏好无法读取，请重新选择。'}}
// 反向定位（从工单/计划/批次的「看成本」进入）：先清空已保存筛选，保证能找到；找到后打开工单抽屉或产品页
let locate:{orderId?:string|null;planId?:string|null;no?:string|null}|null=null
function readUrl(){const q=new URL(location.href).searchParams,v=q.get('costView');if(VIEWS.value.some(x=>x.id===v))view.value=v as View;const l={orderId:cfg.value.initialOrderId,...cfg.value.initialLocate};if(l.orderId||l.planId||l.no){locate=l;keyword.value='';unit.value='';startDate.value='';endDate.value='';scopeProductKey.value='';focus.value='all';dateMode.value='all';view.value='products'}}
function applyLocate(){if(!locate||!report.value)return;const l=locate;locate=null;const all=allOrders.value,hits=all.filter(o=>l.orderId?o.id===l.orderId:l.planId?o.planId===l.planId:o.projectCode===l.no||o.planNumber===l.no);const label=l.no||l.planId||l.orderId
 if(!hits.length){notice.value='没有找到 '+label+' 的成本记录（可能尚无报工或已取消）；未按名称猜配。';return}
 const p=report.value.products.find(p=>p.orders.includes(hits[0]));if(p)productKey.value=p.key
 if(hits.length===1)inspect(hits[0]);else{notice.value=label+' 下有 '+hits.length+' 张工单，已打开所属产品';drawer.value=false;persist()}}
// 报表交给工作区入口（六膳门把它注册成悬浮窗对象的依据，D 的 ai-objects 协议）
const reportNow=()=>report.value
onMounted(()=>{environment.CretasCostScope={current:currentCostScope,report:reportNow};window.addEventListener('cretas:cost-supplement',locateSupplement);restore();readUrl();void load(filters())})
onBeforeUnmount(()=>{if(environment.CretasCostScope?.current===currentCostScope)delete environment.CretasCostScope;generation++;controller?.abort();if(jobTimer!==undefined)window.clearTimeout(jobTimer);window.removeEventListener('cretas:cost-supplement',locateSupplement)})
// 工作区切换：清空当前对象与弹窗，按新工作区自己的偏好恢复
watch(()=>cfg.value.factoryId,()=>{drawer.value=false;editor.value=false;followup.value=false;importing.value=false;report.value=null;productKey.value='';restore();void load(filters())})
// 已在成本页时再从别处「看成本」进来（六膳门 hash 变化）：重新定位
watch(()=>cfg.value.initialOrderId,id=>{if(id){readUrl();void load(filters())}})
const focused=computed(()=>view.value==='products'&&!!selectedProduct.value)
</script>

<template>
 <section class="nuxt-cost-workspace" :class="{'nuxt-cost-focused':focused}" aria-label="成本分析">
  <p v-if="error" role="alert" class="nuxt-error">{{error}}</p><p v-if="notice" role="status" class="nuxt-muted">{{notice}}</p>
  <template v-if="!focused">
  <nav class="nuxt-cost-breadcrumb" aria-label="当前位置"><span>数据与分析</span><span>/</span><span>成本分析</span><span>/</span><strong>{{VIEWS.find(v=>v.id===view)?.name}}</strong></nav>
  <header class="nuxt-cost-heading"><div><h1>成本分析</h1><p class="cost-object"><UBadge color="primary" variant="subtle">{{cfg.label}}</UBadge><span>{{currencyLabel}}</span><span v-if="report?.sourceRevision">快照 {{String(report.sourceRevision).slice(0,8)}} · {{bjTime(report.sourceCheckedAt)}}</span><span class="nuxt-muted">口径：已识别材料＋人工的直接成本，不是完整制造成本</span></p></div>
   <div class="nuxt-demo-row">
    <template v-if="cfg.features.scopeAnalysis&&view!=='gaps'"><UButton label="分析当前筛选" color="neutral" variant="outline" @click="analyze()"/><span class="cost-help" tabindex="0" aria-label="分析当前筛选的说明" title="把当前已应用的筛选交给右下角悬浮窗：哪些产品能比、差在材料还是人工、先补什么。不改数字，不保存。">?</span></template>
    <div class="cost-tools"><UButton label="单据工具" color="neutral" variant="outline" :aria-expanded="toolsOpen" @click="toolsOpen=!toolsOpen"/>
     <div v-if="toolsOpen" class="cost-tools-menu" role="menu" @keydown.escape="toolsOpen=false">
      <button role="menuitem" @click="downloadTemplate">下载补充模板<small>当前筛选 {{supplementable}} 张有工序对应的工单</small></button>
      <button role="menuitem" @click="openImport">导入补充资料<small>预检 → 确认 → 重算；有错整批不保存</small></button>
      <button role="menuitem" @click="exportGaps">导出待补清单<small>按责任人分表（xlsx），含数据时点</small></button>
      <button v-if="cfg.features.weighing" role="menuitem" @click="openBp">副产品分摊口径<small>不分摊 / 按重量 / 按固定比例</small></button>
      <button v-if="cfg.factoryId!=='YDWM'" role="menuitem" @click="toolsOpen=false;currencyOpen=true">补充币种<small>来源未提供币种时由 Cretas 补充</small></button>
      <button v-if="cfg.features.valuation" role="menuitem" @click="toolsOpen=false;openPrice()">补充估值单价<small>进销存估值：黑湖无正价领料时由 Cretas 补充</small></button>
     </div></div>
    <UButton label="刷新数据" :loading="busy" @click="load()"/></div></header>
  <div v-if="lastResult" class="nuxt-review-summary cost-result" role="status"><strong>{{lastResult.label}} · 业务已完成（已回读）</strong><p>已解除：{{lastResult.resolved.join('、')||'无'}}</p><p>仍缺：{{lastResult.still.join('、')||'无'}}</p><UButton label="知道了" size="xs" color="neutral" variant="ghost" @click="lastResult=null"/></div>
  <button v-if="report" class="cost-coverage-strip" @click="chooseView('coverage')"><b>{{cov.ready}} / {{cov.total}}</b> 张工单可算已识别直接成本<template v-if="((report as Report&{cancelledCount?:number}|null)?.cancelledCount??cov.cancelled)">（另有 {{(report as Report&{cancelledCount?:number}|null)?.cancelledCount??cov.cancelled}} 张已取消不计）</template><span v-for="p in cov.primary.slice(0,3)" :key="p.code">{{p.label}} {{p.count}}</span><span v-if="report.blacklakeCost">黑湖成本覆盖 {{report.blacklakeCost.withActual}} / {{report.blacklakeCost.orders}}</span><small>工单数覆盖，不是金额覆盖 · 查看数据覆盖</small></button>
  <nav class="nuxt-demo-row cost-views" aria-label="成本分析视图"><UButton v-for="t in VIEWS" :key="t.id" :label="t.name+(t.id==='gaps'&&report?' '+cov.gapRows.length:'')" :color="view===t.id?'primary':'neutral'" :variant="view===t.id?'soft':'ghost'" size="sm" @click="chooseView(t.id)"/></nav>
  <form v-if="view!=='coverage'&&view!=='wages'" class="nuxt-cost-filters" @submit.prevent="periodKind='';applyFilters()">
   <label>日期范围<select v-model="dateMode" aria-label="成本日期范围"><option value="all">全部记录日期</option><option value="recent">最近有数据的7天</option><option value="custom">自定义日期</option><option value="undated">缺少有效日期</option></select></label>
   <label>产品<select v-model="scopeProductKey" aria-label="筛选成本产品"><option value="">全部产品</option><option v-for="p in report?.filterOptions.products||[]" :key="p.key" :value="p.key">{{p.label}}</option></select></label>
   <label>关注事项<select v-model="focus" aria-label="成本关注事项"><option value="all">全部产品</option><option value="missing">资料待补</option><option value="readiness">口径待核</option><option value="difference">账面差额可对照</option></select></label>
   <UInput v-model="keyword" aria-label="搜索产品或工单" placeholder="产品 / 编码 / 工单号"/><UInput v-model="unit" aria-label="产出单位筛选" placeholder="产出单位"/>
   <div class="nuxt-demo-row"><UButton type="submit" label="搜索"/><UButton label="重置" color="neutral" variant="outline" @click="keyword='';startDate='';endDate='';unit='';scopeProductKey='';focus='all';dateMode='all';periodKind='';applyFilters()"/></div>
   <label v-if="dateMode==='custom'">起始<input v-model="startDate" type="date" aria-label="成本起始日期"/></label><label v-if="dateMode==='custom'">结束<input v-model="endDate" type="date" aria-label="成本结束日期"/></label></form>
  <p v-if="view!=='coverage'&&view!=='wages'" class="nuxt-cost-filter-note">已应用：{{report?.dateContext.label||'读取中'}} · {{report?.dateContext.basis}}。{{report?.dateContext.note}}</p>
  </template>

  <UCard v-if="view==='products'&&!selectedProduct" class="nuxt-cost-card"><template #header><div class="nuxt-cost-heading"><strong>产品汇总</strong><UButton :label="showCharts?'收起对比图':'单位成本图'" color="neutral" variant="ghost" size="xs" @click="showCharts=!showCharts;persist()"/></div></template>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>产品 / 阶段</th><th>工单</th><th>已记录产出</th><th>材料费<small>采用值</small></th><th>人工费<small>采用值</small></th><th>直接成本<small>采用值（材料＋人工）</small></th><th><button class="cost-sort" :aria-sort="sort==='cost'?'descending':'none'" @click="sort=sort==='cost'?'name':'cost';productPage=1;persist()">加权单位成本{{sort==='cost'?' ↓':''}}</button><small>Cretas 计算</small></th><th v-if="report?.blacklakeCost">黑湖单位成本<small>黑湖成本接口</small></th><th>可算</th></tr></thead><tbody>
    <tr v-for="p in pageProducts" :key="p.key"><td><button class="nuxt-cost-link" @click="choose(p)">{{p.product}}</button><small>{{p.productCode||'编码待核对'}} · {{stageName(p.stage)}} · #{{p.productTypeId.slice(-8)}}<template v-if="p.supersededSupplements?.length"> · 补充已被黑湖取代 {{p.supersededSupplements.length}} 项（不参与采用值）</template><template v-else-if="p.orders.some(o=>o.supplementFields?.length)"> · 含 Cretas 补充</template></small></td><td>{{p.orderCount}}<small v-if="p.unlinkedBatchCount">{{p.unlinkedBatchCount}} 张未关联</small></td><td>{{fmt(p.knownOutput)}} {{p.unit}}<small v-if="p.outputPartial">仅已知部分</small></td><td>{{fmt(productAdopted(p,'material').value)}}<small>{{productAdopted(p,'material').src}}<template v-if="productAdopted(p,'material').partial&&productAdopted(p,'material').value!==null"> · 部分记录</template></small></td><td>{{fmt(productAdopted(p,'labor').value)}}<small>{{productAdopted(p,'labor').src}}<template v-if="productAdopted(p,'labor').partial&&productAdopted(p,'labor').value!==null"> · 部分记录</template></small></td><td>{{fmt(productAdopted(p,'direct').value)}}<small v-if="productAdopted(p,'direct').partial">仅已知部分</small></td><td>{{fmt(p.weightedUnitCost)}}<small>{{p.currency==='CNY'?'元':p.currency}} / {{p.unit||'单位待核对'}}</small></td><td v-if="report?.blacklakeCost">{{fmt(p.blWeightedUnitCost)}}<small>黑湖 {{p.blCovered||0}} / {{p.orderCount}} 张</small></td><td><UBadge :color="p.eligibleCount<p.orderCount?'warning':'success'" variant="subtle">{{p.eligibleCount}} / {{p.orderCount}}</UBadge></td></tr>
    <tr v-if="!products.length&&!busy"><td :colspan="report?.blacklakeCost?9:8">当前范围暂无工单，未将缺失成本记作零。</td></tr></tbody></table></div>
   <div class="nuxt-cost-heading"><small>共 {{products.length}} 个产品范围 · 第 {{productPage}} / {{pageCount}} 页</small><div class="nuxt-demo-row"><UButton label="上一页" size="xs" color="neutral" variant="outline" :disabled="productPage<=1" @click="productPage--;persist()"/><UButton label="下一页" size="xs" color="neutral" variant="outline" :disabled="productPage>=pageCount" @click="productPage++;persist()"/></div></div>
   <section v-if="showCharts" class="nuxt-cost-chart" aria-label="产品单位直接成本图"><div class="nuxt-cost-heading"><h3>材料 / 人工单位成本</h3><label>比较单位<select v-model="chartScope" aria-label="成本图表比较单位" @change="persist"><option v-for="c in availableCharts" :key="c.key" :value="c.key">{{c.label}}</option></select></label></div><p class="nuxt-muted">仅比较本页直接成本可用的样本，缺失不补零；点击进入对应产品。</p><p v-if="!chartItems.length">当前页还没有资料齐全的可比样本。</p><button v-for="item in chartItems" :key="item.key" class="nuxt-cost-chart-row" :aria-label="item.label+'，材料单位成本 '+fmt(item.material)+'，人工单位成本 '+fmt(item.labor)" @click="chooseKey(item.key)"><span>{{item.label}}</span><span class="nuxt-cost-bar-track"><span class="nuxt-cost-bar" :style="{width:Math.max(0,(item.material+item.labor)/chartMax*100)+'%'}"><span :style="{width:(item.material+item.labor?item.material/(item.material+item.labor)*100:50)+'%',background:'var(--cs-primary,#1b65a8)'}"/><span :style="{flex:1,background:'#6ca5d7'}"/></span></span><strong>{{fmt(item.material+item.labor)}}</strong></button><p class="nuxt-muted">深蓝：材料 · 浅蓝：人工 · {{selectedChart?.label}}</p></section>
   <p class="nuxt-muted">{{report?.boundary}}</p><p v-if="cfg.features.weighing&&report" class="nuxt-muted" aria-label="称重与副产品口径">报工称重（Cretas 主来源，A 线）：<template v-if="report.weighing?.ready">{{report.weighing.orders}} 张工单完工工序已称重，产出量、出成率、副产品取称重，单位成本按完工良品重量（kg）算（与生产入库同口径）<template v-if="report.weighing.pending">；另有 {{report.weighing.pending}} 张只称了部分工序，产出照旧</template>；</template><template v-else>{{report.weighing?.reason||'未接入'}}，各单照旧；</template>{{report.byproductRule?.text}}<template v-if="report.byproductRule?.at">，设定于 {{bjTime(report.byproductRule.at)}}</template>。<button class="nuxt-cost-link" @click="openBp">改口径</button></p><p v-if="cfg.features.weighing" class="nuxt-muted">{{SOURCE_LEGEND}}</p></UCard>

  <UCard v-else-if="view==='gaps'"><template #header><div class="nuxt-cost-heading"><div><strong>待补资料</strong><p class="nuxt-muted">每张工单只出现一次，按主分类列出；其他原因写在「另有」。先补资料，再看成本差异。</p></div><div class="nuxt-demo-row"><label>找谁<select v-model="gapOwner" aria-label="按责任人筛选" @change="persist"><option value="">全部责任人</option><option v-for="o in owners" :key="o" :value="o">{{o}}</option></select></label><label>缺口<select v-model="gapCode" aria-label="按缺口类型筛选" @change="persist"><option value="">全部类型</option><option v-for="(l,c) in GAP_LABEL" :key="c" :value="c">{{l}}</option></select></label><UButton label="核对缺口" color="neutral" variant="outline" size="sm" title="把当前待补清单交给悬浮窗，按责任人整理找谁补、补什么。不改状态" @click="analyze()"/></div></div></template>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>工单 / 产品</th><th>缺什么</th><th>找谁</th><th>补齐后能解决</th><th>跟进</th><th>操作</th></tr></thead><tbody>
    <tr v-for="{o,g} in gapRows" :key="o.id"><td><button class="nuxt-cost-link" @click="inspect(o,'evidence')">{{o.projectCode}}</button><small>{{o.product}}</small></td><td><UBadge :color="g.blocksUnitCost?'warning':'neutral'" variant="subtle">{{g.label}}</UBadge><small>{{g.reasons.join('；')}}<template v-if="g.others.length"> · 另有：{{g.others.join('、')}}</template></small></td><td>{{g.owner}}</td><td>{{g.unlocks}}</td><td>{{followLabel(o.followup?.status)}}<small v-if="o.followup?.status==='CHECKED'">已核对 · 仍缺 {{o.missing.length}} 项</small></td><td class="cost-row-actions"><UButton label="补充" size="xs" color="neutral" variant="ghost" :disabled="!o.processes.length" :title="o.processes.length?'补充本工单资料':'无工序对应，先回来源核对报工'" @click="openEditor(o)"/><UButton label="跟进" size="xs" color="neutral" variant="ghost" @click="openFollowup(o)"/><a v-if="cfg.sourceLink('plan',o)" class="nuxt-cost-link" :href="cfg.sourceLink('plan',o)!">来源</a></td></tr>
    <tr v-if="!gapRows.length"><td colspan="6">{{cov.gapRows.length?'此筛选下没有待补工单':'当前范围没有待补资料'}}</td></tr></tbody></table></div></UCard>

  <UCard v-else-if="view==='alerts'"><template #header><div class="nuxt-cost-heading"><div><strong>异常与跟进</strong><p class="nuxt-muted">规则发现的候选信号，不是因果结论；阈值为可审查的初始核对值（材料 &lt;10%、人工 &gt;65%、同产品差异 ≥20% 且样本 ≥3）。数据质量缺口在「待补资料」处理，这里不重复列。</p></div></div></template>
   <p class="cost-dq"><b>数据质量</b>：{{cov.gapRows.length}} 张工单有资料缺口 <UButton label="去待补资料" size="xs" color="neutral" variant="ghost" @click="openGaps()"/></p>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>类型</th><th>证据</th><th>阈值</th><th>找谁</th><th>跟进</th><th>操作</th></tr></thead><tbody>
    <tr v-for="s in sig" :key="s.id"><td><UBadge :color="s.family==='business_signal'?'warning':'neutral'" variant="subtle">{{s.title}}</UBadge><small>{{s.family==='business_signal'?'经营信号':'就绪条件'}}</small></td><td>{{s.evidence}}</td><td>{{s.threshold}}</td><td>{{s.owner}}</td><td><template v-if="s.orderIds.length===1">{{followLabel(allOrders.find(o=>o.id===s.orderIds[0])?.followup?.status)}}</template><small v-else>按工单跟进</small></td><td class="cost-row-actions"><UButton label="定位" size="xs" color="neutral" variant="ghost" @click="s.orderIds.length===1?inspect(allOrders.find(o=>o.id===s.orderIds[0])!,'material'):chooseKey(s.productKey)"/><UButton v-if="s.orderIds.length===1" label="跟进" size="xs" color="neutral" variant="ghost" @click="openFollowup(allOrders.find(o=>o.id===s.orderIds[0])!)"/></td></tr>
    <tr v-if="!sig.length"><td colspan="6">当前范围没有触发经营信号或就绪提醒（可算样本少时信号会很少，这是真实空态）。</td></tr></tbody></table></div></UCard>

  <template v-else-if="view==='period'">
   <UCard><template #header><div class="nuxt-cost-heading"><div><strong>周期成本</strong><p class="nuxt-muted">归属口径：{{cfg.features.periodAttribution}}。以最新有数据的日期 {{anchor}} 为锚，北京时间，含首尾两天。这里是所选工单的已识别直接成本，不是期间发生费用。</p></div><div class="nuxt-demo-row" role="group" aria-label="周期快捷"><UButton v-for="k in [['day','日'],['week','周'],['month','月'],['quarter','季'],['year','年'],['custom','自定义']]" :key="k[0]" :label="k[1]" size="xs" :color="periodKind===k[0]?'primary':'neutral'" :variant="periodKind===k[0]?'soft':'ghost'" @click="setPeriod(k[0])"/></div></div></template>
    <div class="nuxt-review-metrics"><div><span>本期工单</span><strong>{{cov.total}}</strong></div><div><span>可算已识别直接成本</span><strong>{{cov.ready}}</strong></div><div><span>可比产品</span><strong>{{(report?.products||[]).filter(p=>p.weightedUnitCost!==null).length}}</strong></div><div><span>本期范围</span><strong class="cost-small">{{report?.dateContext.label}}</strong></div></div>
    <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>产品</th><th>单位</th><th>可算 / 工单</th><th>材料 / 单位<small>Cretas 计算</small></th><th>人工 / 单位<small>Cretas 计算</small></th><th>加权单位成本<small>Cretas 计算</small></th><th v-if="report?.blacklakeCost">黑湖单位成本</th><th v-if="report?.blacklakeCost">黑湖 材料 / 人工</th></tr></thead><tbody><tr v-for="p in (report?.products||[])" :key="p.key"><td><button class="nuxt-cost-link" @click="choose(p)">{{p.product}}</button><small>{{p.productCode||'编码待核对'}}</small></td><td>{{p.unit||'单位待核对'}}</td><td>{{p.eligibleCount}} / {{p.orderCount}}</td><td>{{fmt(p.weightedMaterialUnitCost)}}<small v-if="p.orders.some(o=>o.blacklake?.supersededFields?.length&&unitCost(o)!==null)">含已被黑湖取代的补充（{{p.orders.filter(o=>o.blacklake?.supersededFields?.length&&unitCost(o)!==null).map(o=>o.projectCode).join('、')}}）</small></td><td>{{fmt(p.weightedLaborUnitCost)}}</td><td>{{fmt(p.weightedUnitCost)}}</td><td v-if="report?.blacklakeCost">{{fmt(p.blWeightedUnitCost)}}<small>{{p.blCovered||0}} 张</small></td><td v-if="report?.blacklakeCost">{{fmt(p.blMaterialUnitCost)}} / {{fmt(p.blLaborUnitCost)}}</td></tr><tr v-if="!report?.products.length"><td :colspan="report?.blacklakeCost?8:6">本期没有工单。</td></tr></tbody></table></div>
    <p class="nuxt-muted">不叠加重叠周期，不平均子周期单价；和上期比较需要相同口径的已完成报告，本原型尚未保存周期报告，因此不显示环比。</p></UCard>
   <UCard><template #header><strong>本期分析报告</strong></template>
    <p><UBadge color="neutral" variant="subtle">未运行</UBadge> 每晚 23:55 自动生成报告需要常驻调度，本原型没有运行；下方为按当前范围即时计算的规则结论，不是夜间报告。</p>
    <p>规则结论：{{cov.ready}} / {{cov.total}} 张可算；{{sig.filter(s=>s.family==='business_signal').length}} 条经营信号；主要缺口 {{cov.primary.slice(0,2).map(p=>p.label+' '+p.count).join('、')||'无'}}。</p>
    <template v-if="cfg.features.batchAnalysis">
     <div class="nuxt-demo-row"><UButton :label="report?.analysisJob?.status==='COMPLETE'?'已全部核对':report?.analysisJob?.status==='BLOCKED'?'重试未完成项':'逐单核对当前范围'" :loading="saving||report?.analysisJob?.active" :disabled="!report?.orderCount||report?.analysisJob?.active||report?.analysisJob?.status==='COMPLETE'" @click="startAll"/><small>为当前范围每张工单分别保存核对结果；离开页面后继续，失败只重试未完成项。</small></div>
     <div v-if="report?.analysisJob"><p role="status">解读完成 {{report.analysisJob.completed}} / {{report.analysisJob.total}} · {{({PENDING:'等待开始',RUNNING:'核对中',COMPLETE:'全部核对通过',BLOCKED:'存在待重试项',STALE:'依据或范围已变化'} as Record<string,string>)[report.analysisJob.status]||'待核对'}}</p><p v-if="report.analysisJob.currentLabel">正在处理：{{report.analysisJob.currentLabel}}</p><details v-for="item in report.analysisJob.items" :key="item.id"><summary>{{item.label}} · {{item.status==='COMPLETE'?'已通过':item.status==='BLOCKED'?'待重试':'待核对'}}</summary><div v-if="item.answer" class="cs-ai-answer" v-html="renderAnswer(item.answer)"/><p v-if="item.error" role="alert">{{item.error}}</p><small>尝试 {{item.attempts}} 次；完成项不因重试重复调用。</small></details></div></template>
    <p v-else class="nuxt-muted">本工作区未提供逐单核对；可在单张工单抽屉里用「解读这张工单」逐条解读。</p></UCard>
  </template>

  <UCard v-else-if="view==='wages'"><template #header><div class="nuxt-cost-heading"><div><strong>工价规则</strong><p class="nuxt-muted">计件＝报工良品量×单价（单位一致才算），计时＝报工有效工时×时薪。规则属于 Cretas 补充：不改黑湖报工；黑湖任务工资有值时以黑湖为准，规则结果只作对照，黑湖缺人工费时才补入。</p></div><UButton label="新增规则" @click="ruleForm={processId:'',productCode:'',mode:'time',rate:'',unit:'',effectiveFrom:'',evidence:''};ruleOpen=true"/></div></template>
   <p v-if="wages">报工匹配 <b>{{wages.coverage.matched}} / {{wages.coverage.reports}}</b> 条<span v-for="r in wages.coverage.reasons" :key="r.reason" class="nuxt-muted"> · {{r.reason}} {{r.count}}</span></p>
   <div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>规则</th><th>工序 / 产品</th><th>方式</th><th>单价</th><th>生效</th><th>依据</th><th>操作</th></tr></thead><tbody><tr v-for="r in wages?.rules||[]" :key="r.id" :class="{'cost-revoked':r.revokedAt}"><td>{{r.id}}<small v-if="r.revokedAt">已撤销 · {{r.revokeReason||'原因未记录'}}</small></td><td>{{r.processName||r.processId}}<small>{{r.productCode||'通用（所有产品）'}}</small></td><td>{{r.mode==='piece'?'计件':'计时'}}</td><td>{{fmt(r.rate)}} {{cfg.currencyNote.includes('待')?'（币种待确认）':'元'}} / {{r.unit}}</td><td>{{r.effectiveFrom||'不限'}}</td><td>{{r.evidence}}<small>{{r.at.slice(0,16).replace('T',' ')}}</small></td><td><UButton v-if="!r.revokedAt" label="撤销" size="xs" color="error" variant="ghost" @click="revokeRule(r)"/></td></tr><tr v-if="!wages?.rules.length"><td colspan="7">还没有工价规则。系统不会自动生成规则，请按工资制度逐条填写。</td></tr></tbody></table></div>
   <template v-if="cfg.features.valuation"><h3>补充估值单价（进销存估值用）</h3><p class="nuxt-muted">只在黑湖没有正价领料单价时生效；成品按已识别直接成本估值。新增入口在「单据工具 → 补充估值单价」。</p><div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>物料 / 单位</th><th>单价</th><th>依据</th><th>操作</th></tr></thead><tbody><tr v-for="p in wages?.prices||[]" :key="p.key" :class="{'cost-revoked':p.revokedAt}"><td>{{p.productCode}}<small>{{p.unit}}<template v-if="p.revokedAt"> · 已撤销 · {{p.revokeReason||'原因未记录'}}</template></small></td><td>{{fmt(p.unitPrice)}}</td><td>{{p.evidence}}<small>{{p.at.slice(0,16).replace('T',' ')}}</small></td><td><UButton v-if="!p.revokedAt" label="撤销" size="xs" color="error" variant="ghost" @click="revokePrice(p.key)"/></td></tr><tr v-if="!wages?.prices.length"><td colspan="4">还没有补充估值单价。</td></tr></tbody></table></div></template></UCard>

  <UCard v-else-if="view==='coverage'"><template #header><div class="nuxt-cost-heading"><div><strong>数据覆盖</strong><p class="nuxt-muted">覆盖按工单数计，不是金额覆盖；数字由代码按当前快照计算。</p></div></div></template>
   <div class="nuxt-review-metrics"><div><span>可算 / 有效工单</span><strong>{{cov.ready}} / {{cov.total}}</strong><small>{{cov.total?fmtPct(cov.ready/cov.total):'—'}}</small></div><div><span>不能核算</span><strong>{{cov.blocked}}</strong></div><div><span>已取消（不计）</span><strong>{{(report as Report&{cancelledCount?:number}|null)?.cancelledCount??cov.cancelled}}</strong></div><div><span>来源</span><strong class="cost-small">{{report?.sourceRevision?String(report.sourceRevision).slice(0,8):cfg.label+'工作区'}}</strong><small>{{report?.sourceCheckedAt?.slice(0,16).replace('T',' ')}}</small></div></div>
   <h3>不能核算的原因（互斥主分类）</h3><div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>主分类</th><th>张数</th><th>找谁</th><th>操作</th></tr></thead><tbody><tr v-for="p in cov.primary" :key="p.code"><td>{{p.label}}</td><td>{{p.count}}</td><td>{{cov.gapRows.find(r=>r.g.code===p.code)?.g.owner}}</td><td><UButton label="查看" size="xs" color="neutral" variant="ghost" @click="openGaps(p.code)"/></td></tr><tr v-if="!cov.primary.length"><td colspan="4">当前范围全部可核算。</td></tr><tr class="cost-total"><td>合计</td><td>{{cov.primary.reduce((n,p)=>n+p.count,0)}}</td><td colspan="2"/></tr></tbody></table></div>
   <details><summary>可重叠原因计数（同一工单可计入多类）</summary><table class="nuxt-cost-table"><tbody><tr v-for="p in cov.overlap" :key="p.code"><td>{{p.label}}</td><td>{{p.count}}</td></tr></tbody></table></details>
   <template v-if="report?.blacklakeCost"><h3>黑湖成本接口覆盖</h3><p>快照 {{report.blacklakeCost.revision}} · {{report.blacklakeCost.checkedAt.slice(0,16).replace('T',' ')}}。当前范围 {{report.blacklakeCost.orders}} 张工单：黑湖返回 <b>{{report.blacklakeCost.returned}}</b> 张，有实际成本 <b>{{report.blacklakeCost.withActual}}</b> 张，能算单位成本 <b>{{report.blacklakeCost.unitCostUsable}}</b> 张；合计与 Cretas 计算一致 <b>{{report.blacklakeCost.totalMatch}} / {{report.blacklakeCost.compared}}</b> 张<template v-if="report.blacklakeCost.bothZero">（两边合计都为 0 的 {{report.blacklakeCost.bothZero}} 张不计）</template>。采用值规则：金额类黑湖非 0 才采用黑湖，黑湖记为 0 时按 Cretas 计算或补充；数量类以黑湖为准（R13）。</p><div class="nuxt-cost-scroll"><table class="nuxt-cost-table"><thead><tr><th>不一致原因（材料 / 人工 / 委外 / 其他逐项，可重叠）</th><th>张数</th></tr></thead><tbody><tr v-for="r in report.blacklakeCost.reasons" :key="r.reason"><td>{{r.reason}}</td><td>{{r.count}}</td></tr><tr v-if="!report.blacklakeCost.reasons.length"><td colspan="2">全部一致</td></tr></tbody></table></div></template>
   <h3>字段覆盖</h3><p>领退料行成本有值 {{cov.lineCost.known}} / {{cov.lineCost.total}} 行，其中源端零值 {{cov.lineCost.zero}} 行；工序有效人时已知 {{cov.hours.known}} / {{cov.hours.total}} 道。</p></UCard>

  <ProductCostReview v-if="focused&&selectedProduct" :product="selectedProduct" :config="cfg" :all-orders="allOrders" :cmp="pairs['cmp:'+selectedProduct.key]" @update:cmp="setPair('cmp:'+selectedProduct.key,$event)" :batch-filter="batchScopes[selectedProduct.key]||'all'" :pair="pairs[selectedProduct.key]" @update:batch-filter="setBatchScope(selectedProduct.key,$event)" @update:pair="setPair(selectedProduct.key,$event)" @back="backProducts" @gaps="openGaps()" @inspect="(o,s)=>inspect(o,s)" @analyze="analyze(selectedProduct)" @supplement="openEditor"/>
  <USlideover v-model:open="drawer" :title="currentOrder?.projectCode||'工单成本'" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay nuxt-cost-drawer'}"><template #body><CostBatchDetail v-if="currentOrder" :key="currentOrder.id" :order="currentOrder" :config="cfg" :section-value="batchSections[currentOrder.id]||'material'" @update:section-value="setBatchSection(currentOrder.id,$event)" :saved-analysis="report?.analysisJob?.items.find(i=>i.id===currentOrder?.id)" @analyze="analyzeOrder(currentOrder)" @supplement="openEditor(currentOrder)" @followup="openFollowup(currentOrder)" @related="inspectRelated($event)"/><div v-if="currentOrder&&currentOrder.supplementStatus!=='NONE'&&cfg.factoryId!=='YDWM'" class="nuxt-demo-row cost-revoke"><small>{{currentOrder.supplementStatus==='STALE'?'本工单的 Cretas 补充：源记录已变化，待复核':currentOrder.blacklake?.supplementState?'本工单的 Cretas 补充：'+currentOrder.blacklake.supplementState:'本工单含 Cretas 补充（当前有效）'}}</small><UButton label="撤销补充" size="xs" color="error" variant="ghost" :loading="saving" @click="revoke(currentOrder)"/></div></template></USlideover>
  <UModal :open="editor" title="补充成本资料" :dismissible="!dirty&&!saving" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay nuxt-cost-modal'}" @update:open="v=>{if(!v)closeEditor()}"><template #body><p>{{selectedOrder?.projectCode}} · {{cfg.label}} · 补充只用于分析，不回写{{cfg.factoryId==='YDWM'?'工资或生产账':'黑湖'}}；来源有值时以来源为准。</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p>
   <label>本单人工费<UInput v-model="labor" type="number" min="0" step="0.01" aria-label="本单人工费" :disabled="selectedOrder?.sourceLaborCost!==null" @update:model-value="dirty=true"/><small v-if="selectedOrder?.sourceLaborCost!==null">来源值，直接复用</small></label>
   <label v-if="materialEditable">材料费（估值补充）<UInput v-model="material" type="number" min="0" step="0.01" aria-label="材料费估值补充" placeholder="来源缺失或为 0.00 时填写已核实估值" @update:model-value="dirty=true"/><small>结果会标「含 Cretas 补充」；来源日后给出非零值时，补充值标为「已被来源值取代」。</small></label>
   <p v-if="!processInputs.length" class="nuxt-muted">本工单没有工序对应，只能补材料估值；人工与名单要先回来源核对报工。</p><div v-for="p in processInputs" :key="p.id" class="nuxt-cost-order"><strong>{{p.name}}</strong><small>{{p.source}}</small><label>有效人时<UInput v-model="p.personHours" type="number" min="0" step="0.01" aria-label="有效人时" @update:model-value="dirty=true"/></label><label>实际参与人员代码<UInput v-model="p.workerCodes" aria-label="实际参与人员代码" placeholder="同一人使用同一代码，以逗号分隔" @update:model-value="dirty=true"/></label><label><input v-model="p.zeroConfirmed" type="checkbox" @change="dirty=true"/>已核实零人时</label></div>
   <label>核对依据<UTextarea v-model="evidence" aria-label="核对依据" @update:model-value="dirty=true"/></label><p class="nuxt-muted">人员代码只用于本工厂去重，不返回名单；再次编辑需重新确认。系统和 AI 不会自动生成补充值。</p></template>
   <template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="saving" @click="closeEditor"/><UButton label="保存并重算" :loading="saving" @click="save"/></template></UModal>
  <UModal v-model:open="discard" title="放弃未保存资料？" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay'}"><template #body>原有资料不变，本次输入会清除。</template><template #footer><UButton label="继续编辑" color="neutral" variant="outline" @click="discard=false"/><UButton label="放弃修改" color="error" @click="discard=false;editor=false;dirty=false"/></template></UModal>
  <UModal v-model:open="followup" title="记录跟进" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay'}"><template #body><p>{{selectedOrder?.projectCode}}</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p><label>状态<select v-model="followupStatus" aria-label="跟进状态"><option value="OPEN">未处理</option><option value="MISSING">待补资料</option><option value="CHECKED">已核对</option></select></label><label>本次说明<UTextarea v-model="followupNote" aria-label="跟进说明"/></label><p>已核对只是跟进记录，不清除资料缺口。</p></template><template #footer><UButton label="取消" color="neutral" variant="outline" @click="followup=false"/><UButton label="保存跟进" :loading="saving" @click="saveFollowup"/></template></UModal>
  <UModal v-model:open="importing" title="导入补充资料" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay nuxt-cost-modal'}"><template #body>
   <ol class="cost-steps"><li :class="{on:importStep===1}">1 选择文件</li><li :class="{on:importStep===2}">2 预检</li><li :class="{on:importStep===3}">3 确认导入</li></ol>
   <p>模板范围：当前筛选 {{supplementable}} 张有工序对应的工单（{{report?.dateContext.label}}）。按工单ID、任务/工序ID和源版本对应；已有值自动带出，人员代码需重新确认。<a :href="templateUrl" download @click.prevent="downloadTemplate">下载当前范围模板</a></p>
   <p v-if="error" role="alert" class="nuxt-error">{{error}}</p>
   <input type="file" accept=".xlsx,.xls" aria-label="选择成本补充Excel" @change="fileChanged"/><p>{{uploadName}}</p>
   <div v-if="preview" role="status"><p><b>预检通过</b>：{{preview.batches}} 张工单，共 {{preview.rows}} 行。确认后整批保存；有错整批不保存。</p><table v-if="preview.changes?.length" class="nuxt-cost-table"><thead><tr><th>工单</th><th>保存前</th><th>保存后</th></tr></thead><tbody><tr v-for="c in preview.changes" :key="c.orderId"><td>{{c.projectCode}}</td><td>{{c.before}}</td><td>{{c.after}}</td></tr></tbody></table></div>
   <p class="nuxt-muted">不接受公式；零值和空白分别处理；原始业务数据不覆盖。</p></template>
   <template #footer><UButton label="取消" color="neutral" variant="outline" @click="importing=false"/><UButton label="预检" color="neutral" variant="outline" :disabled="!upload" :loading="saving" @click="previewImport"/><UButton label="确认导入" :disabled="!preview" :loading="saving" @click="confirmImport"/></template></UModal>
  <UModal :open="!!revokeDlg" :title="revokeDlg?.title||'撤销'" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay'}" @update:open="v=>{if(!v)revokeDlg=null}"><template #body><p><b>对象</b>：{{revokeDlg?.target}}</p><p><b>影响</b>：{{revokeDlg?.impact}}</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p><label>撤销原因（必填）<UTextarea v-model="revokeReason" aria-label="撤销原因"/></label></template><template #footer><UButton label="取消" color="neutral" variant="outline" @click="revokeDlg=null"/><UButton label="确认撤销" color="error" :loading="saving" @click="confirmRevoke"/></template></UModal>
  <UModal v-model:open="ruleOpen" title="新增工价规则" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay'}"><template #body><p>{{cfg.label}} · Cretas 补充，不改黑湖报工。指定产品的规则优先于通用规则；生效日不晚于报工日才适用。</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p><label>工序<select v-model="ruleForm.processId" aria-label="工价规则工序"><option value="">请选择</option><option v-for="p in wages?.processes||[]" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>产品编码（可空＝通用）<UInput v-model="ruleForm.productCode" aria-label="工价规则产品编码"/></label><label>方式<select v-model="ruleForm.mode" aria-label="计件或计时"><option value="time">计时（按有效工时）</option><option value="piece">计件（按良品量）</option></select></label><label>单价<UInput v-model="ruleForm.rate" type="number" min="0" step="0.01" aria-label="工价单价"/></label><label v-if="ruleForm.mode==='piece'">计件单位<UInput v-model="ruleForm.unit" aria-label="计件单位" placeholder="与报工单位一致，如 KG"/></label><label>生效日期<input v-model="ruleForm.effectiveFrom" type="date" aria-label="工价生效日期"/></label><label>依据<UTextarea v-model="ruleForm.evidence" aria-label="工价依据"/></label></template><template #footer><UButton label="取消" color="neutral" variant="outline" @click="ruleOpen=false"/><UButton label="保存并重算" :loading="saving" @click="saveRule"/></template></UModal>
  <UModal v-model:open="priceOpen" title="补充估值单价" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay'}"><template #body><p>用于进销存估值。黑湖有正价领料单价时以黑湖为准；成品按已识别直接成本估值，不在这里补。零价不能作为估值。</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p><label>物料编码<UInput v-model="priceForm.productCode" aria-label="估值物料编码"/></label><label>单位<UInput v-model="priceForm.unit" aria-label="估值单位"/></label><label>单价<UInput v-model="priceForm.unitPrice" type="number" min="0" step="0.01" aria-label="估值单价"/></label><label>依据<UTextarea v-model="priceForm.evidence" aria-label="估值依据"/></label></template><template #footer><UButton label="取消" color="neutral" variant="outline" @click="priceOpen=false"/><UButton label="保存" :loading="saving" @click="savePrice"/></template></UModal>
  <UModal v-model:open="bpOpen" title="副产品分摊口径" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay cost-bp-modal'}"><template #body><p>只影响有 Cretas 称重的工单：决定工单直接成本里多少由主产品良品承担，再除以良品重量得到每 kg 成本。金额本身、R13 / R15 规则都不变。</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p><label>口径<select v-model="bpMode" aria-label="副产品分摊口径"><option value="none">不分摊（默认）：成本全部记在主产品</option><option value="weight">按重量：主产品承担 良品 ÷（良品＋副产品）</option><option value="ratio">按固定比例：主产品承担固定百分比</option></select></label><label v-if="bpMode==='ratio'">主产品承担比例（%）<UInput v-model="bpShare" type="number" min="0" max="100" step="0.01" aria-label="主产品承担比例" placeholder="例如 90"/><small v-if="bpShare!==''&&(Number(bpShare)<=0||Number(bpShare)>100)" class="nuxt-error">请填 0 到 100 之间的数（不含 0）</small></label></template><template #footer><UButton label="取消" color="neutral" variant="outline" @click="bpOpen=false"/><UButton label="保存口径" :loading="saving" :disabled="bpMode==='ratio'&&!(Number(bpShare)>0&&Number(bpShare)<=100)" @click="saveBp"/></template></UModal>
  <UModal v-model:open="currencyOpen" title="补充币种" :ui="{overlay:'nuxt-business-overlay',content:'nuxt-business-overlay'}"><template #body><p>{{cfg.label}}来源未提供币种。这里保存的是 Cretas 补充，金额数字不变、不换算；来源日后给出币种时以来源为准。</p><p v-if="error" role="alert" class="nuxt-error">{{error}}</p><label>币种<select v-model="currencyValue" aria-label="币种"><option value="CNY">CNY 人民币</option><option value="USD">USD 美元</option><option value="EUR">EUR 欧元</option></select></label><label>核实依据<UTextarea v-model="currencyEvidence" aria-label="币种核实依据" placeholder="例如：财务确认黑湖成本单价按人民币录入"/></label></template><template #footer><UButton label="取消" color="neutral" variant="outline" @click="currencyOpen=false"/><UButton label="保存币种" :loading="saving" @click="saveCurrency"/></template></UModal>
 </section>
</template>

<style>
.nuxt-cost-workspace .cost-object{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:4px 0 0}
.nuxt-cost-workspace .cost-help,.nuxt-product-review .cost-help{display:inline-grid;place-items:center;width:20px;height:20px;border:1px solid var(--cs-border,#dce4ec);border-radius:50%;font-size:12px;color:var(--cs-muted,#5f6f82);cursor:help}
.nuxt-cost-workspace .cost-tools{position:relative}
.nuxt-cost-workspace .cost-tools-menu{position:absolute;right:0;top:calc(100% + 4px);z-index:30;min-width:260px;padding:4px;background:var(--cs-surface,#fff);border:1px solid var(--cs-border,#dce4ec);border-radius:10px;box-shadow:var(--cs-shadow-overlay,0 8px 24px rgba(15,35,60,.12))}
.nuxt-cost-workspace .cost-tools-menu button{display:block;width:100%;text-align:left;background:none;padding:6px 10px;border-radius:6px}
.nuxt-cost-workspace .cost-tools-menu button:hover{background:var(--cs-primary-soft,#eaf2fa)}
.nuxt-cost-workspace .cost-tools-menu small{display:block;color:var(--cs-muted,#5f6f82);font-size:12px}
.nuxt-cost-workspace .cost-coverage-strip{display:flex;flex-wrap:wrap;gap:12px;align-items:baseline;width:100%;text-align:left;margin:8px 0;padding:8px 12px;background:var(--cs-primary-soft,#eaf2fa);border:1px solid var(--cs-border,#dce4ec);border-radius:10px;cursor:pointer}
.nuxt-cost-workspace .cost-coverage-strip span{color:var(--cs-text,#263648)}.nuxt-cost-workspace .cost-coverage-strip small{margin-left:auto;color:var(--cs-muted,#5f6f82)}
.nuxt-cost-workspace .cost-views{border-bottom:1px solid var(--cs-border,#dce4ec);padding-bottom:4px;margin-bottom:8px}
.nuxt-cost-workspace .cost-sort{background:none;padding:0;min-height:0;font-weight:inherit;color:inherit}
.nuxt-cost-workspace .cost-row-actions,.nuxt-product-review .cost-row-actions{white-space:nowrap}
.nuxt-cost-workspace .cost-row-actions a,.nuxt-product-review .cost-row-actions a{margin-left:6px}
.nuxt-cost-workspace .cost-result{border-left:3px solid var(--cs-success,#29816b)}
.nuxt-cost-workspace .cost-steps{display:flex;gap:12px;list-style:none;padding:0;margin:0 0 8px}.nuxt-cost-workspace .cost-steps li,.nuxt-business-overlay .cost-steps li{color:var(--cs-muted,#5f6f82)}.nuxt-business-overlay .cost-steps{display:flex;gap:12px;list-style:none;padding:0}.nuxt-business-overlay .cost-steps li.on{color:var(--cs-primary,#1b65a8);font-weight:600}
.nuxt-cost-workspace .cost-small{font-size:13px}
.nuxt-product-review .cost-pair label{display:flex;gap:4px;align-items:center;font-size:13px}
.nuxt-product-review .cost-warn{border-left:3px solid var(--cs-warning,#b38336)}
.nuxt-product-review .cost-total td,.nuxt-cost-workspace .cost-total td{font-weight:600}
.nuxt-product-review .cost-group-row td{background:var(--cs-surface-subtle,#f6f8fb)}
.nuxt-batch-review .cost-drawer-actions{margin:6px 0 8px}
.nuxt-batch-review .cost-bl{margin:10px 0;padding:8px 10px;border:1px solid var(--cs-border,#dce4ec);border-radius:8px}
.nuxt-batch-review .cost-ok{color:var(--cs-success,#29816b)}.nuxt-batch-review .cost-warn-text{color:var(--cs-warning,#b38336)}
.nuxt-batch-review .cost-rule-note,.nuxt-batch-review .cost-eff{margin-top:8px;padding:8px 10px;border:1px solid var(--cs-border,#dce4ec);border-radius:8px}
.nuxt-cost-workspace .cost-revoked td{color:var(--cs-muted,#5f6f82);text-decoration:line-through}
.nuxt-business-overlay .cost-revoke{justify-content:space-between;margin-top:12px;padding-top:8px;border-top:1px solid var(--cs-border,#dce4ec)}
.nuxt-cost-breadcrumb{display:flex;gap:6px;align-items:center;font-size:13px;color:var(--cs-muted,#5f6f82)}
.nuxt-cost-table td,.nuxt-cost-table th{padding-top:4px;padding-bottom:4px;line-height:20px}
.nuxt-cost-table td small{display:block}
</style>
<style>
/* 第八批：副产品口径弹窗（弹窗挂在 body 下，用全局样式）：标签在上、输入框在下，不挤一行 */
.cost-bp-modal label{display:flex;flex-direction:column;align-items:stretch;gap:4px;margin:10px 0}
.cost-bp-modal select,.cost-bp-modal input{width:100%;box-sizing:border-box}
